INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 1, 190801, 1, "2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "カリン", 1000001, 0, 2, 3.414, -416.5, 62);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 1, 190801, 2, "2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン", 1000002, 0, 2, 3.099, -416.5, 62);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 1, 190801, 3, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", 1000003, 0, 2, 2.801, -416.5, 63);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 2, 190801, 4, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", "カリン", 1000004, 0, 2, 0, -416.5, 63);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 2, 190801, 5, "2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "カリン", 1000005, 0, 1, 2.12, -363, 64);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 1, 190801, 6, "2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "カリン", 1000006, 0, 2, 1.68, -363, 64);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 1, 2, 190801, 7, "2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "カリン", 1000007, 0, 1, 2.33, -363, 64);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 10201, 3, 133701, 101, "2030/01/01 14:59:59", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "ラビリスタ", 1020101, -6, 7, 5.18, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 10201, 1, 133901, 201, "2030/01/01 14:59:59", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "クリスティーナ", 1020102, -2, 2, 8.77, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/01/31 12:00:00", 10201, 6, 133801, 301, "2030/01/01 14:59:59", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "ネネカ", 1020103, 0, 1, 15.5, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/02/28 12:00:00", 10202, 2, 134301, 101, "2030/01/01 14:59:59", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "ランファ", 1020201, 0, 5, 9.061, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/02/28 12:00:00", 10202, 1, 134401, 201, "2030/01/01 14:59:59", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "チカ", 1020202, 0, 2, 7.699, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/03/31 12:00:00", 10203, 1, 134601, 101, "2030/01/01 14:59:59", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "アオイ", 1020301, 0, 2, 8.595, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/03/31 12:00:00", 10203, 1, 134501, 201, "2030/01/01 14:59:59", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "クローチェ", 1020302, 0, 2, 7.758, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/04/30 12:00:00", 10204, 2, 132302, 101, "2030/01/01 14:59:59", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "ルイズマリー", 1020401, 0, 6, 7, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/04/30 12:00:00", 10204, 1, 132402, 201, "2030/01/01 14:59:59", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "イロハ", 1020402, 0, 2, 7.904, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/04/30 12:00:00", 10204, 4, 132502, 301, "2030/01/01 14:59:59", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "ソノ", 1020403, 0, 2, 8.487, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/05/31 12:00:00", 10205, 1, 134901, 101, "2030/01/01 14:59:59", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "カノン", 1020502, 0, 2, 8.763, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/05/31 12:00:00", 10205, 1, 134801, 201, "2030/01/01 14:59:59", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "ツムギ", 1020503, 0, 3, 6.417, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/06/30 12:00:00", 10206, 3, 135001, 101, "2030/01/01 14:59:59", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "エリス", 1020601, 0, 7, 10.335, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/06/30 12:00:00", 10206, 2, 135101, 201, "2030/01/01 14:59:59", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "シェフィ", 1020602, 0, 4, 6.281, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/06/30 12:00:00", 10206, 1, 135201, 301, "2030/01/01 14:59:59", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "プレシア", 1020603, 0, 2, 12.244, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/07/31 12:00:00", 10207, 2, 135301, 101, "2030/01/01 14:59:59", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "クリア", 1020701, 0, 8, 6.339, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/07/31 12:00:00", 10207, 7, 135401, 201, "2030/01/01 14:59:59", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "アネモネ", 1020702, 0, 9, 8.184, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/08/31 12:00:00", 10208, 9, 129101, 101, "2030/01/01 14:59:59", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "アイラ", 1020801, 0, 2, 3.906, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/08/31 12:00:00", 10208, 1, 129201, 201, "2030/01/01 14:59:59", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "シナツ", 1020802, 0, 2, 14.465, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/08/31 12:00:00", 10208, 4, 100101, 301, "2030/01/01 14:59:59", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "ヒヨリ", 1020803, 0, 3, 8.662, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/08/31 12:00:00", 10208, 1, 100301, 401, "2030/01/01 14:59:59", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "レイ", 1020804, 0, 3, 10.915, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/09/30 12:00:00", 10209, 1, 135802, 101, "2030/01/01 14:59:59", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "ユキノ", 1020901, 0, 7, 6.042, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/09/30 12:00:00", 10209, 4, 135903, 201, "2030/01/01 14:59:59", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "サツキ", 1020902, 0, 1, 9.402, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/09/30 12:00:00", 10209, 8, 136902, 301, "2030/01/01 14:59:59", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "ルルィ", 1020903, 0, 1, 8.16, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/10/31 12:00:00", 10210, 3, 137401, 101, "2030/01/01 14:59:59", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "カスミ", 1021001, 0, 2, 5, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/10/31 12:00:00", 10210, 4, 136001, 201, "2030/01/01 14:59:59", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "アラクネ", 1021002, 0, 1, 8.12, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/10/31 12:00:00", 10210, 4, 136202, 301, "2030/01/01 14:59:59", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "ナーナ", 1021003, 0, 2, 6.386, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/11/30 12:00:00", 10211, 3, 136402, 101, "2030/01/01 14:59:59", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "ユイ", 1021101, 0, 4, 7.438, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/11/30 12:00:00", 10211, 1, 136302, 201, "2030/01/01 14:59:59", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "ミソラ", 1021102, 0, 5, 8.35, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/12/31 12:00:00", 10212, 1, 136501, 101, "2030/01/01 14:59:59", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "シズル", 1021201, 0, 2, 5, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/12/31 12:00:00", 10212, 1, 137902, 201, "2030/01/01 14:59:59", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "リノ", 1021202, 0, 2, 5.25, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2025/12/31 12:00:00", 10212, 1, 106801, 301, "2030/01/01 14:59:59", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "ラビリスタ", 1021203, 0, 2, 7.5, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/01/31 12:00:00", 10213, 1, 126501, 101, "2030/01/01 14:59:59", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "ライラエル", 1021301, 0, 2, 8.204, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/01/31 12:00:00", 10213, 1, 129701, 201, "2030/01/01 14:59:59", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "ネフィ＝ネラ", 1021302, 0, 2, 7.176, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/01/31 12:00:00", 10213, 1, 133101, 301, "2030/01/01 14:59:59", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "ヴァイオレット", 1021303, 0, 5, 8.602, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/06 12:00:00", 10213, 1, 138101, 102, "2030/01/01 14:59:59", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "ライラエル", 1021304, 0, 3, 10.14, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/06 12:00:00", 10213, 1, 138201, 202, "2030/01/01 14:59:59", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "ネフィ＝ネラ", 1021305, 0, 7, 10.152, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/06 12:00:00", 10213, 4, 138001, 302, "2030/01/01 14:59:59", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "ヴァイオレット", 1021306, 0, 3, 9.688, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/12 12:00:00", 10213, 2, 138301, 401, "2030/01/01 14:59:59", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "ペコリーヌ", 1021307, 0, 1, 5.928, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/28 12:00:00", 10214, 4, 138702, 101, "2030/01/01 14:59:59", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "ワカナ", 1021401, 0, 2, 9.19, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/02/28 12:00:00", 10214, 1, 138802, 201, "2030/01/01 14:59:59", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "シオリ", 1021402, 0, 3, 8.724, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/03/31 12:00:00", 10215, 4, 138902, 101, "2030/01/01 14:59:59", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "グレイス", 1021501, 0, 1, 7.758, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/03/31 12:00:00", 10215, 6, 139002, 201, "2030/01/01 14:59:59", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "キョウカ", 1021502, 0, 4, 6.375, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/03/31 12:00:00", 10215, 6, 136902, 301, "2030/01/01 14:59:59", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "ルルィ", 1021503, 0, 1, 6.173, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/30 12:00:00", 10216, 6, 139202, 101, "2030/01/01 14:59:59", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "ミホ", 1021601, 0, 2, 4.202, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/30 12:00:00", 10216, 6, 139302, 201, "2030/01/01 14:59:59", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "マホ", 1021602, 0, 1, 2.842, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/30 12:00:00", 10216, 4, 139402, 301, "2030/01/01 14:59:59", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "エリカ", 1021603, 0, 1, 4.598, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 4, 125802, 101, "2030/01/01 14:59:59", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "リリ", 1021701, 0, 3, 6.533, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 3, 126102, 301, "2030/01/01 14:59:59", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "プレシア", 1021702, 0, 3, 5, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 3, 126002, 201, "2030/01/01 14:59:59", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "クリア", 1021703, 0, 4, 5.214, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 1, 139501, 102, "2030/01/01 14:59:59", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "リリ", 1021704, 0, 3, 8.781, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 2, 139601, 202, "2030/01/01 14:59:59", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "クリア", 1021705, 0, 1, 6.529, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/05/31 12:00:00", 10217, 3, 139701, 302, "2030/01/01 14:59:59", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "プレシア", 1021706, 0, 2, 3.195, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/06/30 12:00:00", 10218, 2, 139902, 101, "2030/01/01 14:59:59", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "ルイズマリー", 1021801, 0, 3, 12.43, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/06/30 12:00:00", 10218, 2, 140001, 201, "2030/01/01 14:59:59", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "クレジッタ", 1021802, 0, 3, 6.35, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/07/31 12:00:00", 10219, 1, 140102, 101, "2030/01/01 14:59:59", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "フブキ", 1021901, 0, 5, 10.23, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/07/31 12:00:00", 10219, 1, 140201, 201, "2030/01/01 14:59:59", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "ヴァンピィ", 1021902, 0, 2, 5.584, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/08/31 12:00:00", 10220, 6, 126401, 201, "2030/01/01 14:59:59", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", "クローチェ", 1022001, 0, 3, 2.8, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/08/31 12:00:00", 10220, 4, 127802, 101, "2030/01/01 14:59:59", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", "ヴルム", 1022002, 0, 3, 8.9, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/08/31 12:00:00", 10220, 2, 140602, 202, "2030/01/01 14:59:59", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", "クローチェ", 1022003, 0, 1, 4.49, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/08/31 12:00:00", 10220, 1, 140501, 102, "2030/01/01 14:59:59", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", "ヴルム", 1022004, 0, 3, 9.42, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/08/31 12:00:00", 10220, 4, 140402, 301, "2030/01/01 14:59:59", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", "リーザ", 1022005, 0, 1, 7, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 1, 141101, 101, "2030/01/01 14:59:59", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "アーモンドアイ", 1022101, 0, 3, 8.61, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 6, 141201, 201, "2030/01/01 14:59:59", "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", "ラッキーライラック", 1022102, 0, 1, 3.55, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 2, 141301, 301, "2030/01/01 14:59:59", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "デアリングタクト", 1022103, 0, 1, 8.26, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 2, 141001, 401, "2030/01/01 14:59:59", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "ゴールドシップ", 1022104, 0, 1, 8.79, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 1, 141101, 101, "2030/01/01 14:59:59", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "アーモンドアイ", 1022105, 0, 3, 8.61, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 1, 141201, 202, "2030/01/01 14:59:59", "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", "ラッキーライラック", 1022106, 0, 2, 2.69, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 2, 141301, 301, "2030/01/01 14:59:59", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "デアリングタクト", 1022107, 0, 1, 8.26, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/10/31 12:00:00", 10221, 2, 141001, 401, "2030/01/01 14:59:59", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "ゴールドシップ", 1022108, 0, 1, 8.79, -285, 61);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 1, 190805, 1, "2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "カリン", 2000001, 0, 2, 3.414, -416.5, 62);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 1, 190805, 2, "2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン", 2000002, 0, 2, 3.099, -416.5, 62);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 1, 190805, 3, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", 2000003, 0, 2, 2.801, -416.5, 63);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 2, 190805, 4, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", "カリン", 2000004, 0, 2, 0, -416.5, 63);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 2, 190805, 5, "2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "カリン", 2000005, 0, 1, 2.12, -363, 64);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 1, 190805, 6, "2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "カリン", 2000006, 0, 2, 1.68, -363, 64);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2026/04/10 12:00:00", 2, 2, 190805, 7, "2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "カリン", 2000007, 0, 1, 2.33, -363, 64);
